ASCII_CHARS = " .:-=+*#%@"

def frame_to_ascii(frame, cols=80, rows=40):
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    resized = cv2.resize(gray, (cols, rows * 2))
    lines = []
    for row in resized:
        line = ""
        for pixel in row:
            idx = int((pixel / 255) * (len(ASCII_CHARS) - 1))
            line += ASCII_CHARS[idx]
        lines.append(line)
    return "\n".join(lines)
